        "beatSystemCopy": {
            "saveTheCatTitle": "Save the Cat",
            "saveTheCatDesc": "Enfatiza los beats emocionales claros y la participación de la audiencia.\n\nÚselo cuando desee puntos de inflexión limpios, inversiones visibles y un fuerte sentido de impulso frente a la audiencia desde la configuración hasta el final.\n\nLo mejor para: Ficción comercial, guiones, género de alto concepto\nPerfil de Momentum: Configuración -> Giro de punto medio -> Pago de cierre",
            "saveTheCatExamples": "Ejemplos: Los Juegos del Hambre, el Marciano, La falla de nuestras estrellas.",
            "saveTheCatSourceLabel": "Libros de Save the Cat de Jessica Brody",
            "herosJourneyTitle": "El viaje del héroe",
            "herosJourneyDesc": "Rastrea la salida, la transformación, la prueba y el regreso.\n\nÚselo cuando desee un arco mítico o impulsado por la identidad con transformación interior y exterior visible.\n\nLo mejor para: Historias de misiones, Ficción especulativa, Viajes transformacionales\nPerfil de Momentum: Salida -> Pruebas -> Ordeal -> Regresar con Cambio",
            "herosJourneyExamples": "Ejemplos: Star Wars, El Hobbit, un mago de Earthsea.",
            "herosJourneySourceLabel": "El viaje del escritor de Christopher Vogler",
            "classicDramaticTitle": "Estructura dramática clásica",
            "classicDramaticDesc": "enfatiza la presión de la escena, los puntos de inflexión, las opciones fundamentales y los resultados consecuentes.\n\nÚselo cuando desee probar el estrés de si cada escena crea movimiento a través del conflicto y el cambio.\n\nLo mejor para: Ficción literaria, Drama, Trabajo de escenas ajustadamente editado, Pases de revisión\nPerfil de Momentum: Configuración → Complicación → Presión → Opción fundamental → Resultado",
            "classicDramaticExamples": "Ejemplos: Orgullo y prejuicio, Hamlet, El Padrino.",
            "podcastArcTitle": "Arco narrativo de podcast",
            "podcastArcDesc": "Formas narraciones habladas en torno a gancho, configuración, desarrollo y recompensa.\n\nÚselo cuando desee una fuerte retención de oyentes y una progresión verbal limpia.\n\nMejor para: Podcasts, ensayos de audio, monólogos, no ficción narrada\nPerfil de Momentum: Hook -> Marco -> Desarrollo -> Reembolso",
            "podcastArcExamples": "Ejemplos: episodios de podcast narrativos, episodios de historias dirigidos por entrevistas, segmentos de audio documental.",
            "youtubeExplainerTitle": "arco explicador de youtube",
            "youtubeExplainerDesc": "Organiza la enseñanza y la explicación en torno a la curiosidad, la claridad y la progresión.\n\nÚselo cuando desee que un espectador entienda algo rápidamente mientras se mantiene comprometido.\n\nMejor para: explicadores, videos educativos, comentarios, tutoriales\nPerfil de impulso: Gancho -> Promesa -> Desglose -> Para llevar",
            "youtubeExplainerExamples": "Ejemplos: explicadores educativos, canales de comentarios, narración basada en tutoriales.",
            "documentaryArcTitle": "Arco narrativo documental",
            "documentaryArcDesc": "Equilibra la cronología, el contexto, las apuestas y las consecuencias en los eventos que se repiten.\n\nÚsalo cuando necesites guiar a la audiencia a través de eventos reales sin perder impulso.\n\nLo mejor para: redacción de historia, estructura documental, narración de historias de no ficción, cronogramas\nPerfil de impulso: Contexto -> Construcción -> Pivote -> Consecuencia",
            "documentaryArcExamples": "Ejemplos: documentales históricos, capítulos de historia narrativa, reconstrucciones de eventos.",
            "romanceLadderTitle": "Escalera de tropos románticos",
            "romanceLadderDesc": "Realiza un seguimiento de la atracción, la tensión, la vulnerabilidad, la ruptura y la recompensa emocional.\n\nÚselo cuando el arco de relación emocional es el motor principal de la inversión del lector.\n\nLo mejor para: Romance, tramas secundarias románticas, pases de química de personajes\nPerfil de impulso: Spark -> Tensión -> Vulnerabilidad -> Ruptura -> Unión/Decisión",
            "romanceLadderExamples": "Ejemplos: enemigos-a-amantes, proximidad forzada, quemadura lenta.",
            "thrillerLadderTitle": "Escalera de escalada de suspenso",
            "thrillerLadderDesc": "Genera presión a través del peligro, la revelación, las reversiones y las opciones de estrechamiento.\n\nÚselo cuando desee cada fase para apretar el riesgo y reducir las opciones seguras del protagonista.\n\nLo mejor para: thrillers, suspenso, tramas de persecución, narrativas de supervivencia\nPerfil de impulso: Amenaza -> Persecución -> Reversión -> Compresión -> Confrontación",
            "thrillerLadderExamples": "Ejemplos: La fugitiva, Gone Girl, El silencio de los corderos.",
            "customTitle": "sistema personalizado",
            "customDesc": "Diseñe su propio marco estructural para este manuscrito. Defina los beats que importan a su historia, ya sea que sigan un arco clásico o Seguimiento de la progresión específica del género.\n\nLos sistemas personalizados pueden representar tropos, giros temáticos, hitos de investigación, fases históricas o cualquier ritmo estructural que desee Medida.",
            "customExamples": "Ejemplos: flujos de trabajo novedosos personalizados, sistemas de revisión a medida, estructuras de aula.",
            "blankCustomTitle": "endurecimiento",
            "blankCustomDesc": "Comienza vacío para que puedas diseñar tu propia estructura desde cero.\n\nÚselo cuando ninguno de los lentes de la biblioteca coincida con su proceso o desee un modelo específico del proyecto.\n\nMejor para: diseño de beat personalizado, experimentación, estructuras híbridas, enseñando su propio método\nPerfil de impulso: definido por el autor",
            "blankCustomExamples": "Comience con al menos 3 beats. Nombra cada beat por función, no por tema. Use una progresión clara como Apertura -> Presión -> Mayús. agregar o Reordenar late solo cuando cada uno tiene un propósito estructural distinto."
        },
