            "glossaryRunningHeaderTerm": "Cabezal de funcionamiento",
            "glossaryRunningHeaderDef": "El texto repetido en la parte superior de cada página interior (título del libro, autor, contexto de escena, número de página, etc.). Las páginas pares e impares pueden llevar Diferentes contenidos en los libros de la página opuesta.",
            "glossaryEvenOddTerm": "Incluso vs página impar",
            "glossaryEvenOddDef": "Convención de impresión: números de página pares (2, 4, 6 …) sentarse en el lado izquierdo (verso) de una extensión abierta; Números impares (1, 3, 5 …) Siéntate a la derecha (Recto). La página 1 siempre es anexado. Pase cualquier tarjeta de esquina para su lado específico de página.",
