        "refactorAlerts": {
            "aiModelSystemTitle": "Sistema de modelo de IA actualizado",
            "aiModelSystemDescription": "Los modelos de IA se están migrando a un nuevo sistema. No se requiere ninguna acción. Consulte Configuración → AI para obtener más detalles y ajuste la configuración para que coincida con sus preferencias personales.",
            "yamlStructureTitle": "YAML Estructura actualizada",
            "yamlStructureDescription": "base y propiedad YAML Los conjuntos ahora están limpiamente separados. El conjunto base define campos centrales; El conjunto de propiedades agrega campos opcionales. Comandos y diseñador de libros ahora fusionarlos automáticamente. Sus conjuntos de campo se han actualizado a la estructura más reciente.",
            "revisionToIterationTitle": "YAML Requiere actualización de campo",
            "revisionToIterationDescription": "El campo \"Revisión\" se ha renombrado a \"Iteración\". Actualice sus propiedades YAML. Las notas existentes con \"Revisión:\" seguirán funcionando.",
            "revisionToIterationTooltip": "Renombrar YAML Campo \"Revisión\" a \"Iteración\" para evitar confusiones y mejorar la estabilidad de la base de código.",
            "pendingEditsTypeTitle": "YAML Cambio de tipo: Pending Edits y actualización de resumen",
            "pendingEditsTypeDescription": "\"Pending Edits\"Ya no es un booleano. Ahora es una cadena, por lo que puede actuar como un indicador de sí/no y registrar la última IA API Hit (marca de tiempo y IA utilizada). Los YAML El campo \"Actualización de resumen\" (anteriormente \"Actualización de sínopsis\") funciona de manera idéntica: valor de cadena con timestamp e IA utilizados.",
            "newFolderTitle": "Carpeta nueva Radial Timeline",
            "newFolderDescription": "Se ha creado una nueva carpeta de Radial Timeline en su bóveda de Obsidian para organizar los archivos según la estructura actualizada, incluidos los registros de API de IA, los Inquiry Briefs, las exportaciones y campañas de Social APR, y otros recursos relacionados.",
            "logFoldersTitle": "Carpetas de registro reorganizadas",
            "logFoldersDescription": "Los registros ahora viven bajo Radial Timeline/logs con carpetas dedicadas para Inquiry, Gossamer, pulso, movimientos, instantáneas y Gossamer archivo. Los registros de contenido de IA completa se almacenan dentro de las subcarpetas de contenido para la función de coincidencia.",
            "recoveryFilesTitle": "Los archivos de recuperación se sacaron de los registros",
            "recoveryFilesDescription": "Las instantáneas y Gossamer Archive — los archivos usados para recuperar datos de notas eliminados o sobrescritos — ahora se encuentran en Radial Timeline/Recover en lugar de Radial Timeline/Logs. La carpeta Logs solo contiene registros de ejecución desechables, por lo que puede vaciarla sin perder datos de recuperación. Si aún existe una carpeta anterior a esta actualización en Radial Timeline/Logs/Snapshots o Radial Timeline/Logs/Gossamer Archive, mueva únicamente esa carpeta a Radial Timeline/Recover para conservar los datos de recuperación anteriores. Advertencia: NO mueva Radial Timeline/Snapshots. Es otra carpeta que Timeline Repair utiliza actualmente para restaurar la cronología; moverla impedirá esa restauración.",
            "inquiryProButtonsTitle": "Inquiry Botones Pro rediseñados",
            "inquiryProButtonsDescription": "EN EL Inquiry Ver, las preguntas progeneradas ahora están marcadas por un número magenta en lugar de un anillo interior. El círculo de puntos solo lleva el estado de ejecución (Listo, Ejecutar, rancio), por lo que cada botón es más fácil de leer de un vistazo. Puramente cosmético: no requiere acción.",
            "templateHotfixTitle": "PDF Plantillas y ejemplos de páginas de libros actualizados",
            "templateHotfixDescription": "Las plantillas de estilo PDF y las plantillas de estilo en línea LaTeX se actualizaron al último formato. Vuelva a exportar para aplicar el nuevo formato."
        },
